#!/usr/bin/env bash

# Phase 0 of the CMake -> xmake migration: parity harness.
#
# Captures the configuration headers generated by the CMake reference build and
# compares them with the headers generated by an xmake build. The CMake build is
# only configured (not compiled), which is enough to resolve every feature probe.
#
# See doc/developing/xmake_migration_plan.md.
#
# Usage:
#   util/ci/parity.sh cmake      Configure the CMake reference build
#   util/ci/parity.sh xmake      Configure + build with xmake (reconfigures the tree!)
#   util/ci/parity.sh compare    Compare the captured headers
#   util/ci/parity.sh all        cmake + xmake + compare
#
# Options:
#   --out DIR           Artifact directory (default: .parity, gitignored)
#   --build-dir DIR     xmake build directory (default: build)
#   --jobs N            Parallel build jobs (default: nproc)
#   --xmake-header FILE Compare against this xmake-generated cmake_config.h
#                       instead of searching the build directory
#
# The reference configuration is pinned here and can be overridden with
# environment variables:
#   PARITY_CMAKE_FLAGS  extra CMake -D flags (space separated)
#   PARITY_XMAKE_FLAGS  extra xmake config flags (space separated)
#
# When overriding, keep both sides in sync, otherwise the comparison is
# meaningless.

set -euo pipefail

ROOT=$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)
OUT="$ROOT/.parity"
BUILD_DIR="$ROOT/build"
JOBS=$(nproc 2>/dev/null || sysctl -n hw.logicalcpu 2>/dev/null || echo 4)
XMAKE_HEADER=""

# Reference configuration: mirrors the Linux CMake CI build (util/ci/build.sh
# with the package set from util/ci/common.sh), with the feature set spelled
# out so it cannot drift with the host.
CMAKE_FLAGS=(
	-DCMAKE_BUILD_TYPE=Debug
	-DENABLE_LTO=FALSE
	-DRUN_IN_PLACE=TRUE
	-DENABLE_GETTEXT=TRUE
	-DBUILD_CLIENT=TRUE
	-DBUILD_SERVER=TRUE
	-DBUILD_UNITTESTS=TRUE
	-DBUILD_BENCHMARKS=FALSE
	-DENABLE_CURSES=OFF
	-DENABLE_SPATIAL=OFF
	-DENABLE_PROMETHEUS=OFF
	-DENABLE_REDIS=ON
	-DENABLE_POSTGRESQL=ON
	-DENABLE_LEVELDB=ON
	-DENABLE_CURL=ON
	-DENABLE_SOUND=ON
	-DENABLE_OPENSSL=ON
	-DENABLE_LUAJIT=ON
)

XMAKE_FLAGS=(
	-m debug
	--run_in_place=y
	--client=y
	--server=y
	--unittests=y
	--benchmarks=n
	--curses=n
	--spatial=n
	--prometheus=n
	--redis=y
	--postgresql=y
	--leveldb=y
	--curl=y
	--sound=y
	--openssl=y
	--luajit=y
	--system_gmp=y
	--system_jsoncpp=y
	--lto=n
)

usage() {
	sed -n '3,30p' "$0" | sed -e 's/^# \{0,1\}//'
}

die() {
	echo "error: $*" >&2
	exit 2
}

normalize_header() {
	# Keep only "#define NAME value" lines and sort them by name.
	sed -nE 's/^[[:space:]]*#define[[:space:]]+([A-Za-z_][A-Za-z0-9_]*)[[:space:]]*(.*)$/\1\t\2/p' "$1" | sort
}

# Macros whose values are expected to differ:
# - ENABLE_UPDATE_CHECKER: CMakeLists.txt has a typo
#   (`set(ENABLE_UPDATE_CHECKER (NOT ${DEVELOPMENT_BUILD}) ...)`), which makes
#   the value always truthy. xmake implements the documented intent.
# - ICON_DIR: unused legacy macro; the install layouts differ until phase 2.
EXPECTED_DIFFS=(ENABLE_UPDATE_CHECKER ICON_DIR)

filter_expected_diffs() {
	local exclude
	exclude=$(IFS='|'; echo "${EXPECTED_DIFFS[*]}")
	grep -vE "^($exclude)" "$1" || true
}

capture_cmake() {
	local build="$OUT/cmake-build"
	mkdir -p "$OUT/cmake"
	echo "==> Configuring CMake reference in $build"
	# shellcheck disable=SC2086
	cmake -S "$ROOT" -B "$build" "${CMAKE_FLAGS[@]}" ${PARITY_CMAKE_FLAGS:-}

	local header
	for header in src/cmake_config.h lib/sha256/cmake_config.h; do
		[ -f "$build/$header" ] || die "missing CMake-generated $header (configure failed?)"
		cp "$build/$header" "$OUT/cmake/$(echo "$header" | tr '/' '_')"
	done
	cp "$build/CMakeCache.txt" "$OUT/cmake/CMakeCache.txt"
	echo "==> Captured CMake reference headers"
}

find_xmake_header() {
	local target=$1
	find "$BUILD_DIR/.gens/$target" -name cmake_config.h -path '*/config/*' 2>/dev/null | head -n1
}

capture_xmake() {
	mkdir -p "$OUT/xmake"
	echo "==> Configuring xmake (this reconfigures the current tree)"
	# shellcheck disable=SC2086
	(cd "$ROOT" && xmake f -c -y "${XMAKE_FLAGS[@]}" ${PARITY_XMAKE_FLAGS:-})
	echo "==> Building with xmake"
	(cd "$ROOT" && xmake build -j"$JOBS")

	local name target header
	for name in luanti sha256; do
		target=$name
		header=$(find_xmake_header "$target")
		[ -n "$header" ] || die "no xmake-generated cmake_config.h for target '$target'"
		cp "$header" "$OUT/xmake/${name}_cmake_config.h"
	done
	echo "==> Captured xmake headers"
}

compare_headers() {
	local failures=0 name cmake_header xmake_header
	for name in luanti sha256; do
		cmake_header="$OUT/cmake/$([ "$name" = luanti ] && echo src_cmake_config.h || echo lib_sha256_cmake_config.h)"
		xmake_header="$OUT/xmake/${name}_cmake_config.h"

		if [ "$name" = luanti ] && [ -n "$XMAKE_HEADER" ]; then
			xmake_header=$XMAKE_HEADER
		else
			local discovered=""
			discovered=$(find_xmake_header "$name" 2>/dev/null || true)
			if [ -n "$discovered" ]; then
				xmake_header=$discovered
			fi
		fi

		[ -f "$cmake_header" ] || die "missing $cmake_header (run: $0 cmake)"
		[ -f "$xmake_header" ] || die "missing $xmake_header (run: $0 xmake, or pass --xmake-header)"

		normalize_header "$cmake_header" > "$OUT/cmake/${name}.norm"
		normalize_header "$xmake_header" > "$OUT/xmake/${name}.norm"
		filter_expected_diffs "$OUT/cmake/${name}.norm" > "$OUT/cmake/${name}.filtered"
		filter_expected_diffs "$OUT/xmake/${name}.norm" > "$OUT/xmake/${name}.filtered"

		echo
		echo "==> $name: cmake vs xmake"
		echo "    (ignoring: ${EXPECTED_DIFFS[*]})"
		if diff -u --label "cmake/$name" --label "xmake/$name" \
				"$OUT/cmake/${name}.filtered" "$OUT/xmake/${name}.filtered"; then
			echo "    identical"
		else
			failures=$((failures + 1))
		fi
	done

	echo
	if [ "$failures" -ne 0 ]; then
		echo "PARITY FAILED: $failures header(s) differ"
		return 1
	fi
	echo "PARITY OK: configuration headers are identical"
}

command=${1:-}
[ $# -gt 0 ] && shift

while [ $# -gt 0 ]; do
	case "$1" in
		--out) OUT=$2; shift 2 ;;
		--build-dir) BUILD_DIR=$2; shift 2 ;;
		--jobs) JOBS=$2; shift 2 ;;
		--xmake-header) XMAKE_HEADER=$2; shift 2 ;;
		-h|--help) usage; exit 0 ;;
		*) die "unknown option: $1 (try --help)" ;;
	esac
done

case "$command" in
	cmake) capture_cmake ;;
	xmake) capture_xmake ;;
	compare) compare_headers ;;
	all) capture_cmake; capture_xmake; compare_headers ;;
	*) usage; exit 2 ;;
esac
